/bin/bash -c "python3 - <<'PY'
from PIL import Image
import numpy as np, cv2
im=np.array(Image.open('first_frame.png').convert('RGB'))
r,g,b=[im[:,:,i] for i in range(3)]
masks={
'black':(r<70)&(g<70)&(b<70),
'darkgray':(r<90)&(g<95)&(b<100),
'white':(r>135)&(g>135)&(b>135)&((np.maximum.reduce([r,g,b]).astype(int)-np.minimum.reduce([r,g,b]))<35),
'bluegray':(b>g-5)&(g>r+5)&(r>100),
'brown':(r>g+10)&(g>b+20)&(r<180),
}
for name,m in masks.items():
 n,lab,stats,cents=cv2.connectedComponentsWithStats(m.astype(np.uint8),8)
 print('\\n',name,'count',m.sum())
 for i in np.argsort(stats[1:,4])[-20:][::-1]+1:
  x,y,w,h,a=stats[i];
  if a>=8: print(f'  area {a:4d} bbox {x:3d},{y:3d} {w:2d}x{h:2d} cent {cents[i,0]:.1f},{cents[i,1]:.1f}')
PY"

